action_input.code:
import json

with open('json/schools.json', 'r') as f:
    data = json.load(f)

# Extract school info for Fresno Unified
fresno_schools = []
for record in data['records']:
    if record.get('District') == 'Fresno Unified':
        fresno_schools.append({
            'CDSCode': record.get('CDSCode'),
            'School': record.get('School'),
            'District': record.get('District'),
            'Phone': record.get('Phone')
        })

print(f"Found {len(fresno_schools)} schools in Fresno Unified")
for s in fresno_schools[:5]:
    print(s)

